    value?: string[];
    defaultValue?: string[];
    onValueChange?: (value: string[]) => void;
    multiple?: boolean;
    placeholder?: string;
    disabled?: boolean;
    className?: string;
    loadOptions?: (query: string, signal: AbortSignal) => Promise<SelectOption[]>;
    label?: string;
    virtual?: boolean;
